package autogradesys.validation;

import java.io.PrintStream;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * The outcome of a {@link SubmissionValidation} run.
 *
 *                    ready for the grader.
 */
// Generated by Claude (Anthropic); reviewed and adapted by the team
/**
 * Stores validation events and the resolved working directories for submissions.
 * @param events the argument supplied to this operation.
 * @param submissions the folder containing submitted student work.
 */
public record ValidationReport(List<ValidationEvent> events, Map<String, Path> submissions) {

    // How many problems were fixed automatically.
    /**
     * Counts validation events that were fixed automatically.
     * @return the result of this operation; an empty, absent, or false result indicates that no matching value or successful update was available.
     */
    public long fixedCount() {
        return events.stream().filter(ValidationEvent::fixed).count();
    }

    // How many problems still need the instructor.
    /**
     * Counts validation events that still require user attention.
     * @return the result of this operation; an empty, absent, or false result indicates that no matching value or successful update was available.
     */
    public long attentionCount() {
        return events.size() - fixedCount();
    }

    // Writes the report to the given stream (the console in the real program).
    /**
     * Writes the current report or diagnostic information to the supplied output stream.
     * @param out the argument supplied to this operation.
     */
    public void print(PrintStream out) {
        out.println();
        out.println("__ Submission validation __");

        // Group the events by student so each student's changes appear together.
        Map<String, List<ValidationEvent>> byStudent = new TreeMap<>();
        for (ValidationEvent event : events) {
            byStudent.computeIfAbsent(event.student(), k -> new ArrayList<>()).add(event);
        }
        for (Map.Entry<String, List<ValidationEvent>> entry : byStudent.entrySet()) {
            out.println(entry.getKey());
            for (ValidationEvent event : entry.getValue()) {
                out.println(event.getLogMessage());
            }
        }

        out.println("Identified " + submissions.size() + " submissions: " + fixedCount()
                + " problems fixed automatically, " + attentionCount() + " still need attention.");
        out.println("(Only the working copy was changed, never the original submissions. Run the submission check again to confirm.)");
        out.println();
    }
}
